'use strict';
const $=id=>document.getElementById(id), M=BUNDLE.model;
const pct=x=>(100*x).toFixed(1)+'%',mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:0;
function predict(x){return 1/(1+Math.exp(-(M.intercept+x.reduce((s,v,i)=>s+(v-M.mean[i])/M.scale[i]*M.coef[i],0))))}
function band(p){return p<.4?'Priority':p<.7?'Check-in':'On track'}
const data=BUNDLE.records.filter(r=>r.split==='test');let shown=50,filtered=[],scenario=[80,75,3.5,4];
const names=['Attendance (%)','Tasks submitted (%)','Mentor feedback (1–5)','Mentor sessions in weeks 1–2'];
document.title='Ocean Analytics · Intern Performance | Internee.pk';
document.querySelector('header small').textContent='OCEAN ANALYTICS / SAJID ALI / INTERNEE.PK';
document.querySelector('h1').innerHTML='Intern Performance Prediction<span>Early engagement. Clearer insights. Personalized mentor support.</span>';
$('theme').textContent='High contrast';
const cohortGrid=$('departments').closest('.grid');cohortGrid.className='oceanrow';
cohortGrid.insertAdjacentHTML('afterbegin','<article><h2>Engagement landscape</h2><p>Attendance × task submissions · hover a point for details</p><div id="scatter" class="chart"></div><div class="legend"><span><i style="background:#ed8a36"></i>Priority</span><span><i style="background:#79bee9"></i>Check-in</span><span><i style="background:#0872bc"></i>On track</span></div></article>');
cohortGrid.appendChild($('departments').closest('article'));
cohortGrid.insertAdjacentHTML('afterend','<div class="grid"><article><h2>Success probability distribution</h2><p>Intern counts by 10-percentage-point probability intervals</p><div id="histogram" class="chart"></div></article><article><h2>Engagement profile</h2><p>Selected cohort averages · normalized to a 0–100 scale</p><div id="profile"></div></article></div><article class="mentorstrip"><h2>Turn signals into support</h2><p id="mentorSummary"></p><p>Discuss attendance barriers, agree on one task milestone, review feedback together and schedule the next check-in. Select <strong>Review</strong> below to prepare an individual plan.</p></article>');
const review=$('rows').closest('article');review.querySelector('h2').insertAdjacentHTML('afterend','<label>Order interns<select id="sort"><option value="low">Lowest probability first</option><option value="high">Highest probability first</option><option value="id">Intern ID</option></select></label>');
review.querySelector('p').textContent='Select Review to load an intern’s week-2 engagement into the prediction studio. Use the ordering control to change the review sequence.';
$('predict').insertAdjacentHTML('beforeend','<article><h2>Attendance sensitivity</h2><p>Vary attendance while holding your other three inputs fixed. This shows model response, not a promised intervention effect.</p><div id="sensitivity" class="chart"></div></article>');
$('quality').querySelector('img').remove();
$('quality').insertAdjacentHTML('beforeend','<div class="grid"><article><h2>ROC curve</h2><p>Discrimination across decision thresholds</p><div id="roc" class="chart"></div></article><article><h2>Calibration curve</h2><p>Estimated probability versus observed success</p><div id="calibration" class="chart"></div></article><article><h2>Prediction outcomes</h2><p>Confusion matrix · fixed classification threshold 0.50</p><div id="confusion"></div></article><article><h2>What influences the estimate?</h2><p>Standardized coefficients · association, not causation</p><div id="coefficients"></div></article></div><a class="button" href="model_evaluation.png" download>Download evaluation image</a>');
const color=p=>p<.4?'#ed8a36':p<.7?'#79bee9':'#0872bc';
function plot(id,points,xlabel,ylabel,{scatter=false,diagonal=false,ymax=1}={}){
 const W=560,H=290,L=55,R=18,T=15,B=48,w=W-L-R,h=H-T-B,x=v=>L+v*w,y=v=>T+h-v/ymax*h;
 let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${xlabel} versus ${ylabel}">`;
 for(let i=0;i<=4;i++){let f=i/4;s+=`<path d="M${L} ${y(f*ymax)}H${W-R}" stroke="#e1ebf3"/><text x="${L-9}" y="${y(f*ymax)+4}" text-anchor="end">${Math.round(f*ymax*100)}%</text><text x="${x(f)}" y="${H-B+23}" text-anchor="middle">${Math.round(f*100)}%</text>`}
 if(diagonal)s+=`<path d="M${x(0)} ${y(0)}L${x(1)} ${y(1)}" stroke="#ed8a36" stroke-dasharray="5 5" fill="none"/>`;
 if(!scatter)s+=`<polyline points="${points.map(p=>x(p[0])+','+y(p[1])).join(' ')}" stroke="#0872bc" stroke-width="3" fill="none"/>`;
 s+=points.map(p=>`<circle cx="${x(p[0])}" cy="${y(p[1])}" r="${scatter?4:3}" fill="${scatter?color(p[2]):'#0872bc'}" opacity="${scatter?.7:1}"><title>${p[3]||`${xlabel}: ${pct(p[0])}; ${ylabel}: ${pct(p[1])}`}</title></circle>`).join('');
 s+=`<text x="${L+w/2}" y="${H-3}" text-anchor="middle">${xlabel}</text><text transform="translate(14 ${T+h/2}) rotate(-90)" text-anchor="middle">${ylabel}</text></svg>`;$(id).innerHTML=s;
}
function cohortCharts(){
 if(!filtered.length){['scatter','bands','histogram','profile'].forEach(id=>$(id).innerHTML='<p class="empty">No records match these filters.</p>');$('mentorSummary').textContent='Reset filters or search for another intern.';return}
 plot('scatter',filtered.map(r=>[r.attendance_pct/100,r.submission_pct/100,r.success_probability,`${r.intern_id} · ${r.department} · attendance ${r.attendance_pct}% · submissions ${r.submission_pct}% · estimated success ${pct(r.success_probability)}`]),'Attendance','Tasks submitted',{scatter:true});
 const groups=['Priority','Check-in','On track'],colors=['#ed8a36','#79bee9','#0872bc'];let offset=0,circles='';
 const counts=groups.map(b=>filtered.filter(r=>band(r.success_probability)===b).length);
 counts.forEach((n,i)=>{const portion=n/filtered.length;circles+=`<circle cx="100" cy="100" r="73" fill="none" stroke="${colors[i]}" stroke-width="24" pathLength="100" stroke-dasharray="${portion*100} ${100-portion*100}" stroke-dashoffset="${-offset}" transform="rotate(-90 100 100)"/>`;offset+=portion*100});
 $('bands').innerHTML=`<div class="donut"><svg viewBox="0 0 200 200" role="img" aria-label="Support distribution">${circles}</svg><div class="center"><strong>${filtered.length}</strong><small>interns selected</small></div></div>`+groups.map((b,i)=>`<div class="legendrow"><span><i style="background:${colors[i]}"></i>${b}</span><strong>${counts[i]} · ${pct(counts[i]/filtered.length)}</strong></div>`).join('');
 const bins=Array(10).fill(0);filtered.forEach(r=>bins[Math.min(9,Math.floor(r.success_probability*10))]++);const max=Math.max(...bins,1);
 $('histogram').innerHTML='<svg viewBox="0 0 560 245" role="img" aria-label="Probability distribution">'+bins.map((n,i)=>{let height=n/max*155;return `<rect x="${42+i*50}" y="${185-height}" width="34" height="${height}" rx="4" fill="${color((i+.5)/10)}"><title>${i*10}–${(i+1)*10}%: ${n} interns</title></rect><text x="${59+i*50}" y="${176-height}" text-anchor="middle">${n}</text><text x="${59+i*50}" y="209" text-anchor="middle">${i*10}–${(i+1)*10}</text>`}).join('')+'<text x="290" y="239" text-anchor="middle">Estimated success probability (%)</text></svg>';
 bars('profile',[['Attendance',mean(filtered.map(r=>r.attendance_pct))/100,filtered.length],['Tasks submitted',mean(filtered.map(r=>r.submission_pct))/100,filtered.length],['Feedback (score ÷ 5)',mean(filtered.map(r=>r.feedback_score))/5,filtered.length],['Mentor contacts (count ÷ 8)',mean(filtered.map(r=>r.mentor_sessions))/8,filtered.length]]);
 $('mentorSummary').innerHTML=`<strong>${counts[0]} interns</strong> are in the priority band; <strong>${counts[1]}</strong> are in the check-in band for this selection.`;
}
function qualityCharts(){plot('roc',BUNDLE.roc,'False positive rate','True positive rate',{diagonal:true});plot('calibration',BUNDLE.calibration,'Mean estimated probability','Observed success',{diagonal:true});const cm=BUNDLE.confusion;$('confusion').innerHTML=`<div class="matrix"><div>Actual ↓<br>Predicted →</div><div>Not successful</div><div>Successful</div><div>Not successful</div><div class="cell"><strong>${cm[0][0]}</strong>True negatives</div><div class="cell error"><strong>${cm[0][1]}</strong>False positives</div><div>Successful</div><div class="cell error"><strong>${cm[1][0]}</strong>False negatives</div><div class="cell"><strong>${cm[1][1]}</strong>True positives</div></div>`;const max=Math.max(...M.coef.map(Math.abs));$('coefficients').innerHTML=M.coef.map((v,i)=>[names[i],v]).sort((a,b)=>Math.abs(b[1])-Math.abs(a[1])).map(([n,v])=>`<div class="bar"><div><span>${n}</span><strong>${v.toFixed(3)}</strong></div><div class="track"><div class="fill" style="width:${Math.abs(v)/max*100}%;background:${v>=0?'#0872bc':'#ed8a36'}"></div></div></div>`).join('')}
function save(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function tab(id){document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id))}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
function bars(id,items){$(id).innerHTML=items.length?items.map(([label,p,n])=>`<div class="bar"><div><span>${label}</span><strong>${pct(p)} · n=${n}</strong></div><div class="track"><div class="fill" style="width:${100*p}%"></div></div></div>`).join(''):'No records match these filters.'}
function cohort(){filtered=data.filter(r=>($('dept').value==='All'||r.department===$('dept').value)&&($('risk').value==='All'||band(r.success_probability)===$('risk').value)&&r.intern_id.toLowerCase().includes($('search').value.toLowerCase())).sort((a,b)=>a.success_probability-b.success_probability);
 $('kpis').innerHTML=[['Held-out interns',filtered.length],['Mean success estimate',filtered.length?pct(mean(filtered.map(r=>r.success_probability))):'—'],['Priority support',filtered.filter(r=>band(r.success_probability)==='Priority').length],['Mean attendance',filtered.length?mean(filtered.map(r=>r.attendance_pct)).toFixed(1)+'%':'—']].map(([l,v])=>`<div class="kpi"><span>${l}</span><strong>${v}</strong></div>`).join('');
 bars('departments',[...new Set(filtered.map(r=>r.department))].map(d=>{let a=filtered.filter(r=>r.department===d);return[d,mean(a.map(r=>r.success_probability)),a.length]}));
 bars('bands',filtered.length?['Priority','Check-in','On track'].map(b=>{let n=filtered.filter(r=>band(r.success_probability)===b).length;return[b,n/filtered.length,n]}):[]);
 if($('sort').value==='high')filtered.reverse();if($('sort').value==='id')filtered.sort((a,b)=>a.intern_id.localeCompare(b.intern_id));
 $('rows').innerHTML=filtered.slice(0,shown).map(r=>`<tr><td>${r.intern_id}</td><td>${r.department}</td><td>${r.attendance_pct}%</td><td>${r.submission_pct}%</td><td>${r.feedback_score}</td><td>${pct(r.success_probability)}</td><td><button data-id="${r.intern_id}">Review</button></td></tr>`).join('');
 $('count').textContent=`Showing ${Math.min(shown,filtered.length)} of ${filtered.length} records`; $('more').hidden=shown>=filtered.length;
 document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{let r=data.find(x=>x.intern_id===b.dataset.id);scenario=M.features.map(f=>r[f]);$('selected').textContent=r.intern_id+' · '+r.department;controls();tab('predict')});
 cohortCharts();
}
function guidance(x){let a=[];if(x[0]<80)a.push('Discuss attendance barriers privately and agree on a realistic weekly participation plan.');if(x[1]<75)a.push('Break the next task into milestones; clarify the rubric and arrange a midweek progress review.');if(x[2]<3.5)a.push('Review feedback together, show a worked example and agree on one specific improvement.');if(x[3]<4)a.push('Offer a scheduled mentor check-in and make the support channel clear.');if(!a.length)a.push('Maintain regular check-ins and offer a stretch task aligned with the intern’s interests.');a.push('Review progress next week. Use this estimate as a conversation aid, never as an automatic decision.');return a}
function controls(){const bounds=[[0,100,.1],[0,100,.1],[1,5,.01],[0,8,1]]; $('sliders').innerHTML=names.map((n,i)=>`<label for="s${i}">${n}: <strong id="v${i}">${scenario[i]}</strong></label><input id="s${i}" type="range" min="${bounds[i][0]}" max="${bounds[i][1]}" step="${bounds[i][2]}" value="${scenario[i]}">`).join('');scenario.forEach((v,i)=>$('s'+i).oninput=e=>{scenario[i]=+e.target.value;$('v'+i).textContent=e.target.value;studio()});studio()}
function studio(){let p=predict(scenario);$('probability').textContent=pct(p);$('group').textContent=band(p)+' · demonstration support band';$('guidance').innerHTML=guidance(scenario).map(t=>'<li>'+t+'</li>').join('');let alt=[Math.min(100,scenario[0]+10),Math.min(100,scenario[1]+10),scenario[2],scenario[3]];bars('comparison',[['Current scenario',p,1],['Hypothetical scenario',predict(alt),1]]);plot('sensitivity',Array.from({length:21},(_,i)=>[i/20,predict([i*5,...scenario.slice(1)])]),'Attendance','Estimated success')}
[...new Set(data.map(r=>r.department))].sort().forEach(d=>$('dept').add(new Option(d,d)));
['dept','risk','search','sort'].forEach(id=>$(id).oninput=()=>{shown=50;cohort()});$('more').onclick=()=>{shown+=50;cohort()};$('reset').onclick=()=>{$('dept').value='All';$('risk').value='All';$('search').value='';$('sort').value='low';shown=50;cohort()};
$('theme').onclick=()=>document.body.classList.toggle('light');$('scenarioReset').onclick=()=>{scenario=[80,75,3.5,4];$('selected').textContent='Custom scenario';controls()};
$('csv').onclick=()=>{let keys=Object.keys(data[0]);save('filtered_test_interns.csv',[keys.join(','),...filtered.map(r=>keys.map(k=>JSON.stringify(r[k])).join(','))].join('\n'),'text/csv')};
$('plan').onclick=()=>save('mentor_guidance.txt','SYNTHETIC DEMO — '+$('selected').textContent+'\n'+names.map((n,i)=>n+': '+scenario[i]).join('\n')+'\nEstimated success: '+pct(predict(scenario))+'\n\n'+guidance(scenario).join('\n'));
$('metrics').innerHTML=['accuracy','precision','recall','f1','roc_auc','brier','cv_auc_mean','cv_auc_std'].map(k=>`<div class="kpi"><span>${k.replaceAll('_',' ')}</span><strong>${BUNDLE.metrics[k].toFixed(3)}</strong></div>`).join('');
$('baseline').textContent=`Prior-only baseline AUC: ${BUNDLE.metrics.baseline_auc.toFixed(3)}; baseline Brier: ${BUNDLE.metrics.baseline_brier.toFixed(3)}. Lower Brier is better. CV mean/std are training-only ROC AUC.`;
cohort();controls();qualityCharts();
